@startuml

class Subscription {
  + type : string
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Service {
  + name : string
}

class WorkoutPlan {
  + frequency : int
}

class Exercise {
  + name : string
  + repetitions : int
}

class MedicalCheck {
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
  + name : string
}

class Diet {
  + description : string
}

class FitnessLevel {
  + level : string
}

class Gym {
  + computeMonthlyBalance()
  + computeYearlyBalance()
  + sendArrearsReminder()
  + sendMedicalCheckReminder()
}

Customer "1" -- "1" Subscription
Customer "1" -- "0..1" WorkoutPlan
Customer "1" -- "0..*" Service
Customer "1" -- "0..*" MedicalCheck
Customer "0..1" -- "0..1" Diet : follows
Customer "0..1" -- "0..1" FitnessLevel : assessed by
MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalStaff "1" -- "*" Diet : defines
MedicalStaff "1" -- "*" FitnessLevel : determines

WorkoutPlan "1" -- "*" Exercise : includes
Gym "1" -- "*" Customer : manages

@enduml

